internal val LOCALE_DISPLAY_NAMES_MY: String =
    "root\u001F5Iအာဖာ\u001Eအဘ်ခါဇီရာ\u001Eအာချေး\u001Eဒန်မဲ\u001Eအဒိုင်ဂီ\u001Eအာဖရိကန်\u001Eအာဂ်ဟိန်း\u001Eအိန်နု\u001Eအာကန်\u001Eအာလီယု\u001Eတောင် အာလ်တိုင်း\u001Eအမ်ဟာရစ်ခ်\u001Eအာရာဂွန်\u001Eအင်ဂလို ဆက္ကစွန်\u001Eအိုဘိုလို\u001Eအန်ဂီကာ\u001Eအာရဗီ\u001Eခေတ်သစ် ရှေ့ဆောင် အာရဗီ\u001Eမာပုချီ\u001Eအာရာပါဟို\u001Eနာ့ဂျဒီ အာရဗစ်\u001Eအာသံ\u001Eအာစု\u001Eအက်စ်တိုးရီးယား\u001Eအာတီကမဲကု\u001Eအာဗာရစ်ခ်\u001Eအာဝါဒီ\u001Eအိုင်မာရ\u001Eအဇာဘိုင်ဂျန်\u001Eအဇာရီ\u001Eဘက်ရှ်ကာ\u001Eဘယ်လူချီ\u001Eဘာလီ\u001Eဘာဆာ\u001Eဘီလာရုစ်\u001Eဘိန်ဘာ\u001Eဘီနာ\u001Eဘူလ်ဂေးရီးယား\u001Eဟာယန်ဗီ\u001Eအနောက် ဘဲလိုချီ\u001Eဘို့ဂျ်ပူရီ\u001Eဘစ်စ်လာမာ\u001Eဘီနီ\u001Eစစ္စီကာ\u001Eအန်နီ\u001Eဘန်ဘာရာ\u001Eဘင်္ဂါလီ\u001Eတိဘက်\u001Eဘရီတွန်\u001Eဗိုဒို\u001Eဘော့စ်နီးယား\u001Eဘူဂစ်စ်\u001Eဘလင်\u001Eကတ်တလန်\u001Eကာယုဂါ\u001Eချတ်ခ်မာ\u001Eချက်ချန်း\u001Eစီဗူအာနို\u001Eချီဂါ\u001Eချမိုရို\u001Eချူကီးစ်\u001Eမာရီ\u001Eချော့တို\u001Eချီပွေဝိုင်ရန်\u001Eချာရိုကီ\u001Eချေယန်း\u001Eဗဟိုဒေသသုံး ကဒ်ဘာသာ\u001Eချီကိုလ်တင်\u001Eခိုစီကန်\u001Eခရီး\u001Eမစ်ချစ်ခ်\u001Eတောင်ပိုင်း အရှေ့ခရီ\u001Eပလိန်းစ် ခရီ\u001Eမြောက်ပိုင်း အရှေ့ခရီ\u001Eမုစ်ခရီး\u001Eကယ်ရိုလိုင်းနား အယ်လ်ဂွန်းကီယန်\u001Eခရီအိုလီ\u001Eချက်\u001Eဆွမ်ပီ ခရီ\u001Eချပ်ချ် စလာဗစ်\u001Eချူဗက်ရှ်\u001Eဝေလ\u001Eဒိန်းမတ်\u001Eဒါကိုတာ\u001Eဒါဂ်ဝါ\u001Eတိုင်တာ\u001Eဂျာမန်\u001Eဩစတြီးယား ဂျာမန်\u001Eအလီမဲန်နစ် ဂျာမန်\u001Eဒယ်လာဝဲလ်\u001Eဒေါ့ဂ်ရစ်ဘ်\u001Eဇာမာ\u001Eဒိုဂရီ\u001Eအနိမ့် ဆိုဘီယန်း\u001Eဒူအလာ\u001Eအလယ်ပိုင်း ဒတ်ချ်\u001Eဒီဗာဟီ\u001Eဂျိုလာ-ဖွန်ရီ\u001Eဒဇွန်ကာ\u001Eဒဇာဂါ\u001Eအမ်ဘူ\u001Eအီဝီ\u001Eအာဖိခ်\u001Eရှေးဟောင်း အီဂျစ်\u001Eအီကာဂျုခ်\u001Eဂရိ\u001Eအင်္ဂလိပ်\u001Eဩစတြေးလျ အင်္ဂလိပ်\u001Eကနေဒါ အင်္ဂလိပ်\u001Eဗြိတိသျှ အင်္ဂလိပ်\u001Eယူကေ အင်္ဂလိပ်\u001Eအမေရိကန် အင်္ဂလိပ်\u001Eယူအက်စ် အင်္ဂလိပ်\u001Eအလယ်ပိုင်း အင်္ဂလိပ်\u001Eအက်စ်ပရန်တို\u001Eစပိန်\u001Eစပိန် (ဥရောပ)\u001Eစပိန် (မက္ကဆီကို)\u001Eအက်စ်တိုးနီးယား\u001Eဘာစ်ခ်\u001Eအီဝန်ဒို\u001Eပါရှန်\u001Eဒါရီ\u001Eဖူလာ\u001Eဖင်လန်\u001Eဖိလစ်ပိုင်\u001Eဖီဂျီ\u001Eဖာရို\u001Eဖော်န်\u001Eပြင်သစ်\u001Eကနေဒါ ပြင်သစ်\u001Eဆွစ် ပြင်သစ်\u001Eကေဂျန် ဖရန့်စ်\u001Eအလယ်ပိုင်း ပြင်သစ်\u001Eဖရန်စီစ်\u001Eမြောက် ဖရီစီရန်\u001Eအရှေ့ ဖရီစီရန်\u001Eဖရူလီယန်း\u001Eအနောက် ဖရီစီရန်\u001Eအိုင်းရစ်ရှ်\u001Eဂါ\u001Eဂါဂုဇ်\u001Eစကော့တစ်ရှ် ဂေးလစ်ခ်\u001Eဂီးဇ်\u001Eကာရီဗာတီ\u001Eဂါလီစီယာ\u001Eအလယ်ပိုင်း အမြင့် ဂျာမန်\u001Eဂူအာရာနီ\u001Eဂိုရိုတာလို\u001Eရှေးဟောင်း ဂရိ\u001Eဆွစ် ဂျာမန်\u001Eဂူဂျာရသီ\u001Eဂူစီး\u001Eမန်းဇ်\u001Eဂွစ်ချင်\u001Eဟာဥစာ\u001Eဟေဒါ\u001Eဟာဝိုင်ယီ\u001Eတောင် ဟိုင်ဒါ\u001Eဟီဘရူး\u001Eဟိန္ဒီ\u001Eဟီလီဂေနွန်\u001Eမုံ\u001Eခရိုအေးရှား\u001Eဆက္ကဆိုနီ\u001Eဟေတီ\u001Eဟန်ဂေရီ\u001Eဟူပါ\u001Eဟော့ကမိုလွမ်\u001Eအာမေးနီးယား\u001Eဟီရဲရို\u001Eအင်တာလင်ဂွါ\u001Eအီဗန်\u001Eအီဘီဘီယို\u001Eအင်ဒိုနီးရှား\u001Eအင်တာလင်း\u001Eအစ္ဂဘို\u001Eစီချွမ် ရီ\u001Eအနောက် ကနေဒီယန် အီနုတီတွတ်\u001Eအီလိုကို\u001Eအင်ဂုရှ်\u001Eအီဒို\u001Eအိုက်စ်လန်\u001Eအီတလီ\u001Eအီနုခ်တီတု\u001Eဂျပန်\u001Eလိုဂျ်ဘန်\u001Eဂွမ်ဘာ\u001Eမချာမီ\u001Eဂျူဒီယို-ပါရှန်\u001Eဂျူဒီယို-အာရဗီ\u001Eဂျာဗား\u001Eဂျော်ဂျီယာ\u001Eကဘိုင်လ်\u001Eကချင်\u001Eဂျူအူ\u001Eကမ်ဘာ\u001Eကဘာဒင်\u001Eတိုင်အပ်\u001Eမာခွန်ဒီ\u001Eကဘူဗာဒီအာနူ\u001Eကိုရို\u001Eကွန်ဂို\u001Eကိန်းဂန်\u001Eခါစီ\u001Eကိုရာ ချီအီနီ\u001Eကီကူယူ\u001Eကွန်းယာမာ\u001Eကာဇာချ\u001Eကကို\u001Eကလာအ်လီဆပ်\u001Eကလန်ဂျင်\u001Eခမာ\u001Eကင်ဘွန်ဒူ\u001Eကန်နာဒါ\u001Eကိုရီးယား\u001Eကိုမီ-ပါမြက်\u001Eကွန်ကနီ\u001Eကပ်ပဲလ်\u001Eကနူရီ\u001Eကရာချေး-ဘာကာ\u001Eကာရီလီယန်\u001Eကူရုပ်ခ်\u001Eကက်ရှ်မီးယား\u001Eရှန်ဘာလာ\u001Eဘာဖီအာ\u001Eကိုလိုနီယန်း\u001Eကဒ်\u001Eကွမ်မိုက်\u001Eကိုမီ\u001Eခိုနီရှ်\u001Eကွပ်ခ်ဝါလာ\u001Eကူဗီ\u001Eကာဂျစ်\u001Eလက်တင်\u001Eလာဒီနို\u001Eလန်ဂီ\u001Eလူဇင်ဘတ်\u001Eလက်ဇ်ဂီးယား\u001Eဂန်ဒါ\u001Eလင်ဘာဂစ်ရှ်\u001Eလက်ဂါးရီရန်\u001Eလာလူးဝစ်တ်\u001Eလာကိုတာ\u001Eလန်းဘတ်\u001Eလင်ဂါလာ\u001Eလာအို\u001Eလူဝီဇီယားနား ခရီးယို\u001Eလိုဇီ\u001Eမြောက်လူရီ\u001Eဆာမိအာ\u001Eလစ်သူဝေးနီးယား\u001Eလူဘာ-ကတန်ဂါ\u001Eလူဘာ-လူလူအာ\u001Eလွန်ဒါ\u001Eလူအို\u001Eမီဇို\u001Eလူရီအာ\u001Eလတ်ဗီးယား\u001Eမဒူရာ\u001Eမဂါဟီ\u001Eမိုင်သီလီ\u001Eမကာဆာ\u001Eမာဆိုင်\u001Eမို့ခ်ရှာ\u001Eမန်ဒဲ\u001Eမီရု\u001Eမောရစ်ရှ\u001Eမာလဂက်စီ\u001Eအလယ်ပိုင်း အိုင်းရစ်ရှ်\u001Eမာခူဝါ-မီအီတို\u001Eမီတာ\u001Eမာရှယ်လိဇ်\u001Eမာအိုရီ\u001Eမစ်ခ်မက်ခ်\u001Eစူကူမီနန်\u001Eမက်ဆီဒိုးနီးယား\u001Eမလေယာလမ်\u001Eမွန်ဂိုလီးယား\u001Eမန်ချူး\u001Eမနိပူရ\u001Eအီနုအေမွန်\u001Eမိုဟော့ခ်\u001Eမိုစီ\u001Eမာရသီ\u001Eမလေး\u001Eမော်လ်တာ\u001Eမွန်ဒန်း\u001Eဘာသာစကား အမျိုးမျိုး\u001Eခရိချ\u001Eမီရန်ဒီးဇ်\u001Eမြန်မာ\u001Eအီဇယာ\u001Eမာဇန်ဒါရန်နီ\u001Eနော်ရူး\u001Eနပိုလီတန်\u001Eနာမာ\u001Eနော်ဝေ ဘွတ်ခ်မော်လ်\u001Eမြောက် အွန်န်ဒီဘီလီ\u001Eအနိမ့် ဂျာမန်\u001Eဂျာမန် (နယ်သာလန်)\u001Eနီပေါ\u001Eနီဝါရီ\u001Eအွန်ဒွန်ဂါ\u001Eနီးရပ်စ်\u001Eနူအဲယန်း\u001Eဒတ်ခ်ျ\u001Eဖလီမစ်ရှ်\u001Eကွာစီအို\u001Eနော်ဝေ နီးနောစ်\u001Eအွန်ရဲဘွန်း\u001Eနော်ဝေ\u001Eနိုဂိုင်\u001Eအွန်ကို\u001Eတောင် အွန်န်ဘီလီ\u001Eမြောက် ဆိုသို\u001Eနူအာ\u001Eနာဗာဟို\u001Eနရန်ဂျာ\u001Eနရန်ကိုလီ\u001Eအိုစီတန်\u001Eအိုဂျစ်ဘွာ\u001Eအိုဂျစ်ဘွေး\u001Eအိုဂျီခရီ\u001Eအနောက် အိုဂျီဘွာ\u001Eအိုကနဂန်\u001Eအိုရိုမို\u001Eအိုရီရာ\u001Eအိုဆဲတစ်ခ်\u001Eပန်ချာပီ\u001Eပန်ဂါစီနန်\u001Eပမ်ပန်ညာ\u001Eပါပီမင်တို\u001Eပလာအို\u001Eနိုင်ဂျီးရီးယား ပစ်ဂျင်\u001Eပါရှန် အဟောင်း\u001Eပါဠိ\u001Eပီဂျင်\u001Eပိုလန်\u001Eမလိဇိ ပါစမ်မကွာဒီ\u001Eပရူရှန်\u001Eပက်ရှ်တွန်း\u001Eပေါ်တူဂီ\u001Eဘရာဇီး ပေါ်တူဂီ\u001Eဥရောပ ပေါ်တူဂီ\u001Eခီချူဝါအိုဝါ\u001Eကီခ်အီချီ\u001Eရာဂျာစတာနီ\u001Eရပန်နူအီ\u001Eရရိုတွန်ဂန်\u001Eရိုဟင်ဂျာ\u001Eရောမ\u001Eရွန်ဒီ\u001Eရိုမေနီယား\u001Eမော်လဒိုဗာ\u001Eရွမ်ဘို\u001Eရုရှ\u001Eအာရိုမန်းနီးယန်း\u001Eကင်ရာဝန်ဒါ\u001Eရူဝမ်\u001Eသင်္သကရိုက်\u001Eဆန်ဒါဝီ\u001Eဆခါ\u001Eဆမ်ဘူရူ\u001Eဆန်တာလီ\u001Eအွန်ဂမ်းဘေး\u001Eဆန်ဂု\u001Eဆာဒီနီးယား\u001Eစစ္စလီ\u001Eစကော့တ်\u001Eစင်ဒီ\u001Eမြောက် ဆာမိ\u001Eစီနာ\u001Eကိုရာဘိုရို ဆမ်နီ\u001Eဆန်ဂို\u001Eအိုင်းရစ် ဟောင်း\u001Eတာချယ်လ်ဟစ်\u001Eရှမ်း\u001Eစင်ဟာလာ\u001Eဆလိုဗက်\u001Eဆလိုဗေးနီးယား\u001Eတောင် လာ့ရှုစတိ\u001Eဆမိုအာ\u001Eတောင် ဆာမိ\u001Eလူလီ ဆာမိ\u001Eအီနာရီ ဆာမိ\u001Eစခိုးလ် ဆာမိ\u001Eရှိုနာ\u001Eဆိုနင်ကေး\u001Eဆိုမာလီ\u001Eအယ်လ်ဘေးနီးယား\u001Eဆားဘီးယား\u001Eဆရာနန် တွန်ဂို\u001Eဆွာဇီလန်\u001Eဆာဟို\u001Eတောင်ပိုင်း ဆိုသို\u001Eဆဲလစ်ရှ် ရေလက်ကြား\u001Eဆူဒန်\u001Eဆူကူမာ\u001Eဆွီဒင်\u001Eဆွာဟီလီ\u001Eကွန်ဂို ဆွာဟီလီ\u001Eကိုမိုရီးယန်း\u001Eဆီးရီးယား\u001Eစလီရှန်\u001Eတမီးလ်\u001Eတောင် တပ်ချွန်\u001Eတီလီဂူ\u001Eတင်မ်နဲ\u001Eတီဆို\u001Eတီတွမ်\u001Eတာဂျစ်\u001Eတာဂစ်ရှ်\u001Eထိုင်း\u001Eတဟီတန်\u001Eတီဂ်ရင်ယာ\u001Eတီဂရီ\u001Eတာ့ခ်မင်နစ္စတန်\u001Eကလင်ဂွန်\u001Eတလင်းဂစ်\u001Eတီဆဝါနာ\u001Eတွန်ဂါ\u001Eတိုကီပိုနာ\u001Eတော့ခ် ပိစင်\u001Eတူရကီ\u001Eတရိုကို\u001Eဆွန်ဂါ\u001Eတာတာ\u001Eမြောက် တပ်ချွန်\u001Eတမ်ဘူကာ\u001Eတူဗာလူ\u001Eတာဆာဝါချ\u001Eတဟီတီ\u001Eတူဗန်\u001Eအလယ်အာ့တလာစ် တာမာဇိုက်\u001Eအူမူရတ်\u001Eဝီဂါ\u001Eယူကရိန်း\u001Eအူဘန်ဒူ\u001Eမသိသော ဘာသာ\u001Eအူရ်ဒူ\u001Eဥဇဘတ်\u001Eဗိုင်\u001Eဗင်န်ဒါ\u001Eဗနီးရှန်\u001Eဗီယက်နမ်\u001Eမတ်ကူးဝါး\u001Eဗိုလာပိုက်\u001Eဗွန်ဂျို\u001Eဝါလူးန်\u001Eဝေါလ်ဆာ\u001Eဝိုလက်တာ\u001Eဝါရေး\u001Eဝေါလ်ပီရီ\u001Eဝူလိုဖ်\u001Eဝူ တရုတ်\u001Eကာလ်မိုက်\u001Eဇိုစာ\u001Eခန်းဂရီ\u001Eဆိုဂါ\u001Eရန်ဘဲန်\u001Eရမ်ဘာ\u001Eရဟူဒီ\u001Eယိုရူဘာ\u001Eအန်ဟင်းဂတူ\u001Eကွမ်းတုံ\u001Eဂျွမ်\u001Eမိုရိုကို တမဇိုက်\u001Eတရုတ်\u001Eဇူးလူး\u001Eဇူနီ\u001Eဘာသာစကားနှင့် ပတ်သက်သောအရာ မရှိပါ\u001Eဇာဇာ\u001F5Jအက်ဒ်လမ်\u001Eအာရေဗျ\u001Eနက်စ်တာလိခ်\u001Eအာမေးနီးယား\u001Eဘင်္ဂါလီ\u001Eဘိုပို\u001Eဗွဟ်မမီ\u001Eဘရေ\u001Eချပ်ခ်မာ\u001Eကင်န်စ်\u001Eချာရိုကီး\u001Eစစ်ရိလစ်\u001Eဒီဗနာဂရီ\u001Eအီသီယိုးပီးယား\u001Eဂျော်ဂျီယာ\u001Eဂရိ\u001Eဂုဂျာရသီ\u001Eဂူရူ\u001Eဟန်ဘ်\u001Eဟန်ဂူးလ်\u001Eဟန်\u001Eရိုးရှင်း\u001Eရိုးရာ\u001Eဟီဗရူး\u001Eဟီရဂန\u001Eဂျပန် အက္ခရာ\u001Eဂျမို\u001Eဂျာဗားနီးစ်\u001Eဂျပန်\u001Eကယားလီ\u001Eခတခန\u001Eခမာ\u001Eခန်နာဒါ\u001Eကိုရီးယား\u001Eလာအို\u001Eလက်တင်\u001Eမလေယာလမ်\u001Eမွန်ဂိုလီးယား\u001Eမေတဲမာယက်\u001Eမြန်မာ\u001Eအွန်ကို\u001Eအိုလ်ချီကီ\u001Eအိုရာ\u001Eဟာနီဖီ\u001Eဆင်ဟာလ\u001Eဆူဒန်\u001Eဆီရီရက်ခ်\u001Eတိုင်လီ\u001Eတမီးလ်\u001Eတယ်လူဂူ\u001Eတီဖီနော\u001Eတဂလော့ဂ်\u001Eသာအ်\u001Eထိုင်း\u001Eတိဘက်\u001Eဗိုင်း\u001Eမြင်နိုင်သော စကား\u001Eပါရှန် အဟောင်း\u001Eရီ\u001Eဂဏန်းသင်္ချာ\u001Eအီမိုဂျီ\u001Eသင်္ကေတ\u001Eထုံးတမ်းသဖွယ်လိုက်နာလျက်ရှိသော\u001Eအများနှင့်သက်ဆိုင်သော\u001Eမသိ သို့မဟုတ် မရှိသော စကားလုံး\u001F08ကမ္ဘာ\u001Eအာဖရိက\u001Eမြောက် အမေရိကတိုက်\u001Eတောင် အမေရိက\u001Eသမုဒ္ဒရာဒေသ\u001Eအနောက် အာဖရိက\u001Eဗဟို အမေရိက\u001Eအရှေ့ အာဖရိက\u001Eမြောက် အာဖရိက\u001Eအလယ် အာဖရိက\u001Eအာဖရိက တောင်ပိုင်း\u001Eအမေရိကန်\u001Eမြောက် အမေရိက\u001Eကာရစ်ဘီယံ\u001Eအရှေ့အာရှ\u001Eတောင်အာရှ\u001Eအရှေ့တောင်အာရှ\u001Eတောင်ဥရောပ\u001Eဩစတြေးလျနှင့် နယူးဇီလန်\u001Eမီလာနီးရှား\u001Eမိုက်ခရိုနီးရှား ဒေသ\u001Eပိုလီနီရှား\u001Eအာရှ\u001Eအလယ်အာရှ\u001Eအနောက်အာရှ\u001Eဥရောပ\u001Eအရှေ့ ဥရောပ\u001Eမြောက် ဥရောပ\u001Eအနောက် ဥရောပ\u001Eဆာဟာရ-အောက်ပိုင်း အာဖရိက\u001Eလက်တင်အမေရိက\u001Eအဆန်းရှင်းကျွန်း\u001Eကလစ်ပါတန်ကျွန်း\u001Eဆာ့က်\u001Eဒီအဲဂိုဂါစီရာ\u001Eဆယ်ဥတာနှင့်မယ်လီလ်လာ\u001Eဥရောပသမဂ္ဂ\u001Eဥရောပဒေသ\u001Eကနေရီ ကျွန်းစု\u001Eသမုဒ္ဒရာ အပြင်ဘက်ရှိ ကျွန်းနိုင်ငံများ\u001Eထရစ္စတန် ဒါ ကွန်ဟာ\u001Eကုလသမဂ္ဂ\u001Eနိုင်ငံခြားသံ\u001Eစာပြောင်းပြန်\u001Eကိုဆိုဗို\u001Eမသိ (သို့) မရှိသော ဒေသ\u001F03\u001E{0}/ {1}\u001E{0}- {1}\u001F0"

